#include <iostream>
#include <string>

class Engine {
public:
    Engine(int hp = 150) : horsepower{hp} {
        std::cout << "Engine ctor (" << horsepower << "hp)\n";
    }
    ~Engine() {
        std::cout << "Engine dtor (" << horsepower << "hp)\n";
    }
    int getHp() const { return horsepower; }
private:
    int horsepower;
};

class Car {
    // Friend function declaration
    friend void inspectVehicle(const Car& c);
public:
    Car(const std::string& name, int hp)
        : model{name}, engine{hp} // engine initialized before Car ctor body
    {
        std::cout << "Car ctor (" << model << ")\n";
    }

    ~Car() {
        std::cout << "Car dtor (" << model << ")\n";
    }

    // Safe const reference return preventing external mutation
    const std::string& getModel() const {
        return model;
    }

private:
    std::string model;
    Engine engine; // Composed object
};

void inspectVehicle(const Car& c) {
    // Direct access to private members thanks to friend
    std::cout << "[Inspector] Model: " << c.model 
              << ", Power: " << c.engine.getHp() << "hp\n";
}

int main() {
    {
        Car myCar{"Sedan", 200};
        inspectVehicle(myCar);
    }
    std::cout << "Exited scope\n";
    return 0;
}

#include <iostream>

class Counter {
public:
    // C++17 inline static data member
    inline static int objectCount{0};

    Counter(int val = 0) : value{val} {
        ++objectCount;
    }

    ~Counter() {
        --objectCount;
    }

    // Method chaining using *this
    Counter& increment() {
        ++value;
        return *this;
    }

    Counter& add(int amount) {
        value += amount;
        return *this;
    }

    void display() const {
        std::cout << "Value: " << this->value << "\n";
    }

    // Static member function (has no this pointer)
    static int getCount() {
        return objectCount;
    }

private:
    int value;
};

int main() {
    std::cout << "Initial count: " << Counter::getCount() << "\n";

    Counter c1{10};
    // Cascaded member function calls enabled by returning *this
    c1.increment().add(5).increment();
    c1.display();

    {
        Counter c2{50};
        std::cout << "Count with c2: " << Counter::getCount() << "\n";
    }

    std::cout << "Final count: " << Counter::getCount() << "\n";
    return 0;
}
